198:   const rng = mulberry32(seed);
199:   const tile = size / 2;
200:   ctx.fillStyle = bump ? '#868686' : '#b9ad8a';
201:   ctx.fillRect(0, 0, size, size);
202: 
203:   for (let ty = 0; ty < 2; ty++) {
204:     for (let tx = 0; tx < 2; tx++) {
205:       const ox = tx * tile;
206:       const oy = ty * tile;
207:       const dark = rng() > 0.5;
208:       ctx.fillStyle = bump
209:         ? `rgba(${dark ? 100 : 150},${dark ? 100 : 150},${dark ? 100 : 150},0.16)`
210:         : dark
211:           ? 'rgba(120,108,76,0.12)'
212:           : 'rgba(214,203,166,0.12)';
213:       ctx.fillRect(ox, oy, tile, tile);
214: 
215:       // perforation speckle
216:       for (let i = 0; i < 1200; i++) {
217:         const x = ox + rng() * tile;
218:         const y = oy + rng() * tile;
219:         const r = 0.5 + rng() * 1.8;
220:         ctx.fillStyle = bump
221:           ? `rgba(30,30,30,${0.1 + rng() * 0.3})`
222:           : `rgba(76,67,43,${0.05 + rng() * 0.16})`;
223:         ctx.beginPath();
224:         ctx.arc(x, y, r, 0, TAU);
225:         ctx.fill();
226:       }
227: 
228:       // water stains on some tiles
229:       if (rng() > 0.32) {
230:         const cx = ox + tile * (0.2 + rng() * 0.6);
231:         const cy = oy + tile * (0.2 + rng() * 0.6);
232:         paintStain(ctx, size, cx, cy, 28 + rng() * 70, bump ? '45,45,45' : '98,76,35', bump ? 0.24 : 0.2, seed + tx * 3 + ty);
233:       }
234: 
235:       // occasional broken/dark tile
236:       if (rng() > 0.86) {
237:         ctx.fillStyle = bump ? 'rgba(20,20,20,0.4)' : 'rgba(38,32,18,0.35)';
238:         ctx.fillRect(ox + 4, oy + 4, tile - 8, tile - 8);
239:       }
240:     }
241:   }
242: 
243:   // T-bar grid
244:   ctx.fillStyle = bump ? 'rgba(20,20,20,0.55)' : 'rgba(77,69,48,0.62)';
245:   ctx.fillRect(0, 0, size, 5);
246:   ctx.fillRect(0, tile - 2, size, 5);
247:   ctx.fillRect(0, 0, 5, size);
248:   ctx.fillRect(tile - 2, 0, 5, size);
249:   ctx.fillStyle = bump ? 'rgba(220,220,220,0.18)' : 'rgba(217,206,170,0.22)';
250:   ctx.fillRect(0, 5, size, 1);
251:   ctx.fillRect(5, 0, 1, size);
252: 
253:   addPixelNoise(ctx, size, rng, bump ? 30 : 12);
254: }
