258: /* ------------------------------------------------------------------ */
259: 
260: function paintCardboard(ctx, size, seed) {
261:   const rng = mulberry32(seed);
262:   ctx.fillStyle = '#8a6c42';
263:   ctx.fillRect(0, 0, size, size);
264: 
265:   for (let y = 0; y < size; y += 6) {
266:     ctx.fillStyle = `rgba(60,44,22,${0.06 + rng() * 0.08})`;
267:     ctx.fillRect(0, y, size, 1.5);
268:   }
269:   for (let i = 0; i < 500; i++) {
270:     const x = rng() * size;
271:     const y = rng() * size;
272:     ctx.fillStyle = `rgba(${rng() > 0.5 ? '190,158,104' : '58,43,20'},${0.03 + rng() * 0.08})`;
273:     ctx.fillRect(x, y, 1 + rng() * 5, 1 + rng() * 2);
274:   }
275:   // packing tape
276:   ctx.fillStyle = 'rgba(200,180,130,0.25)';
277:   ctx.fillRect(size * 0.47, 0, size * 0.08, size);
278:   paintStain(ctx, size, size * 0.7, size * 0.8, size * 0.25, '50,35,14', 0.18, seed);
279:   addPixelNoise(ctx, size, rng, 20);
280: }
