291:   g.addColorStop(0.7, 'rgba(255,205,110,0.04)');
292:   g.addColorStop(1, 'rgba(255,200,100,0)');
293:   ctx.fillStyle = g;
294:   ctx.fillRect(0, 0, size, size);
