301: function paintExit(ctx, w, h) {
302:   ctx.fillStyle = '#060806';
303:   ctx.fillRect(0, 0, w, h);
304:   ctx.strokeStyle = 'rgba(80,255,150,0.25)';
305:   ctx.lineWidth = 2;
306:   ctx.strokeRect(3, 3, w - 6, h - 6);
307: 
308:   ctx.font = `bold ${Math.floor(h * 0.58)}px "Courier New", monospace`;
309:   ctx.textAlign = 'center';
310:   ctx.textBaseline = 'middle';
311:   ctx.shadowColor = 'rgba(80,255,150,0.9)';
312:   ctx.shadowBlur = 18;
313:   ctx.fillStyle = '#b8ffd1';
314:   ctx.fillText('EXIT', w / 2, h / 2 + 2);
315:   ctx.shadowBlur = 4;
316:   ctx.fillStyle = '#e9fff1';
317:   ctx.fillText('EXIT', w / 2, h / 2 + 2);
318: 
319:   // arrow
320:   ctx.shadowBlur = 0;
321:   ctx.fillStyle = 'rgba(184,255,209,0.8)';
322:   ctx.beginPath();
323:   ctx.moveTo(w * 0.84, h * 0.5);
324:   ctx.lineTo(w * 0.91, h * 0.5);
325:   ctx.lineTo(w * 0.91, h * 0.4);
326:   ctx.lineTo(w * 0.97, h * 0.54);
327:   ctx.lineTo(w * 0.91, h * 0.68);
328:   ctx.lineTo(w * 0.91, h * 0.58);
329:   ctx.lineTo(w * 0.84, h * 0.58);
330:   ctx.closePath();
331:   ctx.fill();
332: }
