for ... x in [-8,8], y [0,3], z [-8,8]
const dustGeo = new BufferGeometry; position attr copy? 
const dust = new THREE.Points(dustGeo, new THREE.PointsMaterial({ color:0xffe2a8, size:0.022, sizeAttenuation:true, transparent:true, opacity:0.28, depthWrite:false, blending:AdditiveBlending, map: textures.glow }));
