 if (state!=='intro') return;
 audio.init(); audio.start();
 resetSession(true, false?) ... // but world already has chunks for start seed; reseed would clear and re-add. fine.
 intro fade; body playing; state=playing; ...
 clock.getDelta();
 showToast('LEVEL 0 — KEEP MOVING');
