Camera update:
```js
function updateCamera(dt) {
  const zoomFactor = zoomHeld ? ZOOMS[zoomStep] : 1;
  const targetFov = BASE_FOV / zoomFactor;
  fovCurrent += (targetFov - fovCurrent) * (1 - Math.exp(-6*dt));
  camera.fov = fovCurrent; camera.updateProjectionMatrix();
  const speed = Math.hypot(vel.x, vel.y);
  const speedFrac = Math.min(1, speed/RUN);
  walkPhase += speed*dt*2.2;
  const bob = Math.sin(walkPhase*2)*0.022*speedFrac + Math.sin(walkPhase)*0.006*speedFrac;
  const rollBob = Math.sin(walkPhase)*0.007*speedFrac;
  const t=elapsed;
  let shakeMul = 1 + (zoomFactor - 1) * 0.45;
