function updatePlayer(dt) {
  const fwd = (keys.KeyW||keys.ArrowUp?1:0) - (keys.KeyS||keys.ArrowDown?1:0) + stickY;
  const strafe = (keys.KeyD||keys.ArrowRight?1:0) - (keys.KeyA||keys.ArrowLeft?1:0) + stickX;
  let ix=fwd, iz=strafe;
  const len=Math.hypot(ix,iz);
  if (len>1) {ix/=len; iz/=len;}
  const sprinting = (keys.ShiftLeft||keys.ShiftRight||sprintHeld) && len>0.1 && stamina>0.5;
  if (sprinting) { stamina = Math.max(0, stamina - 21*dt); staminaCool=1.1; }
  else { staminaCool=Math.max(0,staminaCool-dt); if (staminaCool<=0) stamina=Math.min(100, stamina+13*dt); }
  const speed = sprinting ? RUN : WALK;
  const fx=-Math.sin(player.yaw), fz=-Math.cos(player.yaw);
  const rx=Math.cos(player.yaw), rz=-Math.sin(player.yaw);
  const tx=(fx*ix + rx*iz)*speed;
  const tz=(fz*ix + rz*iz)*speed;
  const accel = len>0.01 ? 11 : 9;
  vel.x += (tx-vel.x)*(1-Math.exp(-accel*dt));
  vel.y += (tz-vel.y)*(1-Math.exp(-accel*dt));
  const dx=vel.x*dt, dz=vel.y*dt;
  const beforeX=player.x, beforeZ=player.z;
  const tmp = {x: player.x+dx, z: player.z+dz};
  world.resolveCircle(tmp, 0.32);
  player.x = tmp.x; player.z = tmp.z;
  const moved = Math.hypot(player.x-beforeX, player.z-beforeZ);
  distance += moved;
  // footstep accumulation
  stepAccum += moved;
  const stride = sprinting ? 1.3 : 1.75;
  if (stepAccum > stride) { stepAccum=0; audio.footstep(sprinting); }
  // camera roll target
  cameraRollTarget = -iz*0.012; // strafe right -> roll? 
  return {sprinting, moving: len>0.05};
}
