const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch({ args: ['--no-sandbox', '--use-gl=swiftshader', '--enable-unsafe-swiftshader'] });
  const ctx = await browser.newContext({ viewport: { width: 1050, height: 700 } });
  const page = await ctx.newPage();
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));

  await page.goto('http://localhost:3002/', { waitUntil: 'load' });
  await page.waitForTimeout(1200);
  await page.screenshot({ path: 'screenshots/final-intro.png' });

  await page.click('#start-btn').catch(() => {});
  await page.waitForTimeout(2500);
  const state1 = await page.evaluate(() => window.__backrooms && window.__backrooms.state);
  await page.screenshot({ path: 'screenshots/final-game.png' });

  // keyboard movement
  await page.keyboard.down('w');
  await page.waitForTimeout(1200);
  await page.keyboard.up('w');
  const pos = await page.evaluate(() => {
    const b = window.__backrooms;
    return b ? { x: b.player.x, z: b.player.z, state: b.state, chunks: b.world.chunks.size } : null;
  });

  // zoom
  await page.keyboard.down('z');
  await page.waitForTimeout(500);
  const zoom = await page.evaluate(() => window.__backrooms.camera.fov);
  await page.keyboard.up('z');

  // pause/resume
  await page.keyboard.press('p');
  await page.waitForTimeout(400);
  const paused = await page.evaluate(() => window.__backrooms.state);
  await page.keyboard.press('p');
  await page.waitForTimeout(400);
  const resumed = await page.evaluate(() => window.__backrooms.state);

  // entity spawn
  await page.evaluate(() => window.__backrooms.entity.spawnNear(8));
  await page.waitForTimeout(800);
  const entity = await page.evaluate(() => {
    const e = window.__backrooms.entity;
    return { active: e.active, visible: e.group.visible };
  });
  await page.screenshot({ path: 'screenshots/final-entity.png' });

  console.log(JSON.stringify({ state1, pos, zoom, paused, resumed, entity, errors }, null, 2));
  await browser.close();
})();

