const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch({ args: ['--no-sandbox', '--use-gl=swiftshader', '--enable-unsafe-swiftshader'] });
  const ctx = await browser.newContext({
    viewport: { width: 844, height: 390 },
    isMobile: true,
    hasTouch: true,
    deviceScaleFactor: 2,
  });
  const page = await ctx.newPage();
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  page.on('pageerror', e => errors.push(e.message));
  await page.goto('http://localhost:3002/?touch=1', { waitUntil: 'load' });
  await page.waitForTimeout(1000);
  await page.screenshot({ path: 'screenshots/final-mobile-intro.png' });
  await page.tap('#start-btn');
  await page.waitForTimeout(2000);
  const layout = await page.evaluate(() => {
    const ids = ['stick-zone', 'btn-zoom', 'btn-run', 'btn-pause'];
    return ids.map(id => {
      const el = document.getElementById(id);
      if (!el) return { id, missing: true };
      const r = el.getBoundingClientRect();
      const s = getComputedStyle(el);
      return { id, x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height), display: s.display, opacity: s.opacity };
    }).concat([{ state: window.__backrooms.state }]);
  });
  const before = await page.evaluate(() => ({ fov: window.__backrooms.camera.fov, yaw: window.__backrooms.player.yaw }));
  await page.tap('#btn-zoom');
  await page.waitForTimeout(600);
  const after = await page.evaluate(() => ({ fov: window.__backrooms.camera.fov }));
  await page.waitForTimeout(600);
  await page.screenshot({ path: 'screenshots/final-mobile-game.png' });
  console.log(JSON.stringify({ layout, before, after, errors }, null, 2));
  await browser.close();
})();

